// ============================================================
//  PMS Self-Assessment — Score Calculator
//  Based on the Q005 Make.com blueprint.
//
//  15 yes/no questions. Typeform applies ×2 weight per yes,
//  so each Yes = 2 points. Max weighted score = 30.
//
//  Scoring tiers — mirroring the Q005 blueprint switch exactly:
//    weighted score = 0        → Result 1 (No symptoms)
//    weighted score 1–14       → Result 2 (Mild–Moderate)
//    weighted score 15–30      → Result 3 (Moderate–Severe)
//    weighted score 31+        → Result 4 (Severe / PMDD)
//      (Result 4 is not reachable at ×2 with 15 questions,
//       but is kept to match the blueprint exactly.)
// ============================================================

const data = $input.first().json.body || $input.first().json;

const fields = [
  'q1_fluid_retention',
  'q2_backache',
  'q3_breast_tenderness',
  'q4_headache',
  'q5_weight_gain',
  'q6_fatigue',
  'q7_cravings',
  'q8_joint_swelling',
  'q9_irritability',
  'q10_anxiety',
  'q11_mood_swings',
  'q12_depression',
  'q13_hostility',
  'q14_emotional_crying',
  'q15_mental_confusion'
];

let weightedScore = 0;
let rawYesCount = 0;
const scores = {};
const warnings = [];

for (const field of fields) {
  const raw = data[field];
  const isYes = raw && String(raw).trim().toLowerCase() === 'yes';
  const score = isYes ? 2 : 0; // ×2 weight matching Typeform
  scores[field] = { raw, score };
  weightedScore += score;
  if (isYes) rawYesCount++;
  if (raw === undefined || raw === null || raw === '') {
    warnings.push(field + ' is missing');
  }
}

// Four-tier result — matching Q005 Make.com switch logic exactly
let resultNum, resultLabel, resultContent;
if (weightedScore === 0) {
  resultNum = 1;
  resultLabel = 'No Symptoms Reported';
  resultContent = 'You have not reported any PMS symptoms. Your hormonal cycle appears to be well-balanced. Maintaining a healthy lifestyle and monitoring for any future changes is all that is recommended at this time.';
} else if (weightedScore >= 1 && weightedScore <= 14) {
  resultNum = 2;
  resultLabel = 'Mild PMS Symptoms';
  resultContent = 'You are experiencing mild PMS symptoms. These may be managed with dietary changes, targeted supplementation (magnesium, B6), and regular exercise. A hormone panel can confirm whether a progesterone imbalance is contributing to your symptoms.';
} else if (weightedScore >= 15 && weightedScore <= 30) {
  resultNum = 3;
  resultLabel = 'Moderate to Severe PMS';
  resultContent = 'Your symptoms are significantly impacting your quality of life. This level of PMS commonly indicates oestrogen dominance or progesterone deficiency. We recommend a comprehensive hormone panel and a consultation with one of our specialists to discuss treatment options including bioidentical progesterone therapy.';
} else {
  resultNum = 4;
  resultLabel = 'Severe Symptoms / Possible PMDD';
  resultContent = 'Your symptom score is very high and may indicate PMDD (Premenstrual Dysphoric Disorder). This is a recognised medical condition with effective treatments available. Please speak to one of our specialists as soon as possible.';
}

return [{ json: {
  patientName:    data.first_name   || '',
  patientEmail:   data.email        || '',
  mailingList:    data.mailing_list || '',
  weightedScore,
  rawYesCount,
  resultNum,
  resultLabel,
  resultContent,
  _debug_scores:   scores,
  _debug_warnings: warnings
}}];

const d = $input.first().json;
// Escape only the dynamic name used in the HTML greeting.
function escapePatientName(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const greeting = d.patientName ? ('Dear ' + escapePatientName(d.patientName)) : 'Hi there';
const year = new Date().getFullYear();

const introMap = {
  1: `PMS (Premenstrual Syndrome) affects up to 75% of women of reproductive age to some degree. Symptoms are caused by the natural fluctuation of oestrogen and progesterone in the second half of the menstrual cycle.<br/><br/>Based on your responses, you are not currently reporting PMS symptoms — which is a great sign. Your hormone levels appear to be well-balanced through your cycle. However, PMS can develop or worsen with age, particularly in your 30s and 40s as progesterone levels become less stable.<br/><br/>We recommend maintaining healthy lifestyle habits — regular exercise, a low-sugar diet, adequate sleep, and stress management — as these are the most powerful tools for keeping your hormones in balance over time.`,
  2: `PMS is caused by the natural drop in progesterone in the luteal phase (the second half of the menstrual cycle). Even a mild drop can trigger symptoms like fluid retention, breast tenderness, fatigue, mild irritability, and food cravings in the days before your period.<br/><br/>Based on your responses, you are experiencing mild PMS symptoms. The good news is that mild PMS responds very well to targeted nutritional support — particularly magnesium, vitamin B6, and evening primrose oil — alongside dietary adjustments (reducing sugar and caffeine before your period) and regular exercise.<br/><br/>A hormone panel measuring your progesterone and oestradiol levels in the luteal phase can confirm whether low progesterone is driving your symptoms and open the door to more targeted treatment if needed.`,
  3: `Moderate-to-severe PMS is one of the most common yet under-treated hormonal conditions affecting women. What you are experiencing is real, measurable, and most importantly — treatable.<br/><br/>At this level, PMS is most commonly driven by oestrogen dominance (relatively high oestrogen versus progesterone) and/or progesterone deficiency in the luteal phase. The result is a combination of physical symptoms (bloating, breast pain, headaches, joint swelling) alongside emotional and cognitive symptoms (mood swings, anxiety, depression, irritability, mental confusion) that can make the second half of your cycle feel very difficult to manage.<br/><br/>Bioidentical progesterone therapy has an excellent track record in significantly reducing moderate-to-severe PMS symptoms, with most women noticing improvement within 2–3 cycles. Combined with targeted nutritional support, dietary changes, and stress management, this approach addresses the root hormonal cause rather than just masking symptoms.`,
  4: `The symptoms you are experiencing are at a level that may indicate PMDD (Premenstrual Dysphoric Disorder) — a more severe form of PMS characterised by debilitating emotional and physical symptoms in the luteal phase that resolve after menstruation begins.<br/><br/>PMDD is a recognised medical condition, not a personality trait or something to simply endure. The intense mood disturbances, hostility, depression, and physical symptoms you experience each cycle are driven by an abnormal sensitivity to normal hormonal fluctuations — something that can be addressed with the right treatment.<br/><br/>Effective options include bioidentical progesterone therapy, selective serotonin reuptake inhibitors (SSRIs) used specifically during the luteal phase, and comprehensive hormonal assessment to identify the specific drivers of your symptoms. Please do not suffer in silence — our specialists understand what you are going through and are here to help.`
};

const introText = introMap[d.resultNum] || introMap[2];

const labTests = [
  {
