    title: 'Female Hormone Panel — At Home Test Kit',
    desc: 'Measures FSH, LH, oestradiol, and progesterone from a simple blood spot collected at home. Ideal for identifying the hormonal drivers of PMS and monitoring treatment.',
    price: '$179.00',
    url: 'https://store.hrt.org/products/female-hormone-panel-at-home-test-kit'
  },
